UPDATE MSF_REQUEST_SVC_CHG
SET SCAN_ID = #{scanId},
    SIGN_TGT_SBST = COALESCE(NULLIF(#{signTgtSbst}, ''), SIGN_TGT_SBST)

    , FILE_NM = #{fileNm}
    , FILE_MASK_NM = #{fileMaskNm}

WHERE REQUEST_KEY = #{requestKey}

UPDATE MSF_REQUEST_SVC_CHG_DTL
SET SCAN_ID = #{scanId}

  , FILE_NM = #{fileNm}
  , FILE_MASK_NM = #{fileMaskNm}

WHERE REQUEST_KEY = #{requestKey}
  AND SVC_TGT_CD = #{svcTgtCd}

UPDATE MSF_REQUEST_SVC_CHG_DTL
SET SCAN_ID = #{scanId}

  , FILE_NM = #{fileNm}
  , FILE_MASK_NM = #{fileMaskNm}

WHERE REQUEST_KEY = #{requestKey}
  AND SVC_TGT_CD = #{svcTgtCd}
  AND SOC_CD = #{socCd}

  AND PROC_TYPE_CD = #{procTypeCd}

UPDATE MSF_REQUEST_SVC_CHG_DTL
SET PROC_DT = NOW(),
    PROC_CD = #{procCd},
    RES_CD = #{resCd},
    RES_MSG = #{resMsg},
    RES_NO = #{resNo}
WHERE REQUEST_KEY = #{requestKey}
  AND SVC_TGT_CD = #{svcTgtCd}

  AND SOC_CD = #{socCd}


  AND PROC_TYPE_CD = #{procTypeCd}
